<?php
require_once '_bootstrap.php';require_admin_permission('bookings.manage');$db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);try{if($action==='toggle'){$db->execute_query("UPDATE cancellation_policies SET status=IF(status='active','inactive','active') WHERE id=?",[$id]);admin_audit($db,'toggle','cancellation_policy',(string)$id);redirect_with_message('cancellation-policies.php','Cancellation policy status updated.');}$name=trim($_POST['name']??'');$days=max(0,(int)($_POST['minimum_days_before']??0));$percentage=(float)($_POST['refund_percentage']??-1);$fee=max(0,(float)($_POST['administrative_fee']??0));$effective=trim($_POST['effective_from']??'');if($name===''||$percentage<0||$percentage>100||!DateTimeImmutable::createFromFormat('!Y-m-d',$effective))throw new RuntimeException('Enter a valid policy, day threshold, refund percentage, fee, and effective date.');if($id)$db->execute_query('UPDATE cancellation_policies SET name=?,minimum_days_before=?,refund_percentage=?,administrative_fee=?,effective_from=? WHERE id=?',[$name,$days,$percentage,$fee,$effective,$id]);else{$db->execute_query('INSERT INTO cancellation_policies(name,minimum_days_before,refund_percentage,administrative_fee,effective_from) VALUES(?,?,?,?,?)',[$name,$days,$percentage,$fee,$effective]);$id=$db->insert_id;}admin_audit($db,'save','cancellation_policy',(string)$id,$name);redirect_with_message('cancellation-policies.php','Cancellation policy saved.');}catch(Throwable $error){redirect_with_message('cancellation-policies.php'.($id?'?edit='.$id:''),$error->getMessage());}}
$edit=null;if(!empty($_GET['edit']))$edit=$db->execute_query('SELECT * FROM cancellation_policies WHERE id=?',[(int)$_GET['edit']])->fetch_assoc();$policies=$db->query('SELECT * FROM cancellation_policies ORDER BY minimum_days_before DESC,id');$pageTitle='Cancellation Policies';include '_header.php';?>
<div class="page-head"><div><span>Booking governance</span><h1>Cancellation Policies</h1><p>Configure estimated customer refunds by the number of days remaining before departure.</p></div></div>
<section class="panel"><div class="panel-head"><h2><?php echo $edit?'Edit policy':'Add policy';?></h2><?php if($edit):?><a href="cancellation-policies.php">Cancel edit</a><?php endif;?></div><form method="post" class="admin-form"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><input type="hidden" name="action" value="save"><label>Policy name<input name="name" value="<?php echo e($edit['name']??'');?>" maxlength="150" required></label><label>Minimum days before departure<input type="number" min="0" name="minimum_days_before" value="<?php echo e($edit['minimum_days_before']??0);?>" required></label><label>Refund percentage<input type="number" min="0" max="100" step="0.01" name="refund_percentage" value="<?php echo e($edit['refund_percentage']??0);?>" required></label><label>Administrative fee (INR)<input type="number" min="0" step="0.01" name="administrative_fee" value="<?php echo e($edit['administrative_fee']??0);?>"></label><label>Effective from<input type="date" name="effective_from" value="<?php echo e($edit['effective_from']??date('Y-m-d'));?>" required></label><div class="form-actions"><button><i class="fa-solid fa-floppy-disk"></i> Save policy</button></div></form></section>
<section class="panel"><div class="panel-head"><h2>Refund schedule</h2></div><div class="table-wrap"><table><thead><tr><th>Policy</th><th>Threshold</th><th>Refund</th><th>Fee</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($policy=$policies->fetch_assoc()):?><tr><td><strong><?php echo e($policy['name']);?></strong><small>Effective <?php echo e(date('d M Y',strtotime($policy['effective_from'])));?></small></td><td><?php echo (int)$policy['minimum_days_before'];?>+ days</td><td><?php echo e($policy['refund_percentage']);?>%</td><td><?php echo inr($policy['administrative_fee']);?></td><td><span class="pill"><?php echo e($policy['status']);?></span></td><td><div class="action-row"><a class="icon-btn" href="?edit=<?php echo (int)$policy['id'];?>" title="Edit"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$policy['id'];?>"><input type="hidden" name="action" value="toggle"><button class="icon-btn" title="Toggle status"><i class="fa-solid fa-toggle-<?php echo $policy['status']==='active'?'on':'off';?>"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div></section><?php include '_footer.php';?>
